// [START auth_sign_out_react]
import { getAuth, signOut } from "firebase/auth";

function SignOutButton() {
  async function handleSignOut() {
    const auth = getAuth();
    try {
      await signOut(auth);
      // Sign-out successful.
    } catch (error) {
      // An error happened.
    }
  }

  return <button onClick={handleSignOut}>Sign out</button>;
}
// [END auth_sign_out_react]